import {useState, use} from 'react'

import {GitHubAvatar} from '@github-ui/github-avatar'
import {useGetHovercardAttributesForType} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import type {GetHovercardAttributesForTypeFn} from '@github-ui/hovercards/use-get-hovercard-attributes-for-type'
import {MetadataPreviewTable, MetadataDrawer} from '@github-ui/platform-patterns/MetadataTable'
import {useQuery} from '@github-ui/react-query'
import {ActionList, Link, Spinner} from '@primer/react'
import {useAnnounceAsyncStates} from '@github-ui/secret-scanning/hooks'

import {TokenVerificationStatus, verificationStatusToText} from '../../../types/alert-types'

import type {Alert} from '../../../types/alert-types'
import type {Repository} from '../../../types/repo-types'
import type {TokenMetadata} from '../../../types/token-metadata-types'

import type {PartnerTokenMetadata} from '../../../api/metadata'
import {validationQueries} from '../../../api/validation'
import {MetadataKeys} from '../metadata/MetadataKeys'
import {formattedDateString, formatMetadata} from '../metadata/utils'

import {formatOrgAccess, useGetOrgAccess} from './use-get-org-access'
import {useGetPartnerData} from './use-get-partner-data'
import {TimelineContext} from '../../shared/TimelineContext'

const PREVIEW_FIELDS = [
  MetadataKeys.Secret,
  MetadataKeys.SecretIssuedDate,
  MetadataKeys.SecretOwner,
  MetadataKeys.UserName,
  MetadataKeys.Email,
]

export function TokenMetadataPreview({
  alert: {label, token_type_provider, number, partner_metadata_supported, raw_secret, validity, secret_metadata},
  repo,
  // This is old GitHub-specific token metadata included in initial payload.
  tokenMetadata: githubTokenMetadata,
  partnerMetadataEnabled = false,
  includeStoredMetadata = false,
}: {
  alert: Alert
  repo: Repository
  tokenMetadata?: TokenMetadata
  partnerMetadataEnabled?: boolean
  includeStoredMetadata?: boolean
}) {
  const {signalTimelineRefetch} = use(TimelineContext)
  const getHovercardAttributesForType = useGetHovercardAttributesForType()
  const [isDrawerOpen, setIsDrawerOpen] = useState(false)

  const orgAccessValue = useGetOrgAccess({alertNumber: number, repo, tokenMetadata: githubTokenMetadata})

  const {data: validityData} = useQuery(validationQueries.validationCache(number))

  const isPartnerMetadataEnabled =
    partner_metadata_supported && (partnerMetadataEnabled || token_type_provider === 'GitHub')
  const resolvedValidity = validityData?.validity ?? validity
  const isTokenActive = resolvedValidity === TokenVerificationStatus.TOKEN_VALIDITY_ACTIVE

  const metadataQuery = useGetPartnerData({
    alertNumber: number,
    enabled: isPartnerMetadataEnabled && isTokenActive && !secret_metadata && !githubTokenMetadata,
    repo,
    validity: resolvedValidity,
    // The stored-metadata flow creates a METADATA_CREATED timeline event server-side when this
    // component fetches metadata on mount, so refetch the timeline once to surface that event.
    onMetadataFetched: includeStoredMetadata ? signalTimelineRefetch : undefined,
  })
  const {loadingMsg, errorMsg} = useAnnounceAsyncStates({
    query: metadataQuery,
    loadingMsg: 'Loading metadata for secret...',
    errorMsg: 'Error loading metadata for secret',
  })

  const metadataItems = []

  if (raw_secret)
    metadataItems.push({
      field: MetadataKeys.Secret,
      value: raw_secret,
      trailingContent: /\n/.test(raw_secret) ? (
        <pre className="tmp-py-2 overflow-auto">{raw_secret}</pre>
      ) : (
        <pre className="tmp-py-2 ws-pre-wrap wb-break-word">{raw_secret}</pre>
      ),
      showCopyButton: true,
    })

  metadataItems.push({
    field: MetadataKeys.Validity,
    value: verificationStatusToText(validityData?.validity ?? validity),
  })

  if (includeStoredMetadata) {
    metadataItems.push(
      ...buildMetadataItemsForTokenType(
        metadataQuery.data || secret_metadata,
        repo.owner_display_login,
        getHovercardAttributesForType,
        includeStoredMetadata,
      ),
    )
  } else {
    if (githubTokenMetadata)
      metadataItems.push(...buildGitHubTokenMetadataItems(githubTokenMetadata, getHovercardAttributesForType))
    metadataItems.push(...buildPartnerMetadataItems(metadataQuery.data, includeStoredMetadata))
  }

  if (orgAccessValue)
    metadataItems.push({
      field: MetadataKeys.OrganizationAccess,
      value: orgAccessValue,
    })

  // Add unique id for DataTable row rendering
  const itemsWithIds = metadataItems.map((item, index) => ({...item, id: index}))

  // Show only a subset of fields in the preview if there are more than the max number of preview fields
  const previewItems =
    itemsWithIds.length > PREVIEW_FIELDS.length
      ? itemsWithIds.filter(({field}) => PREVIEW_FIELDS.includes(field))
      : itemsWithIds

  // Show drawer if there are more items than the preview
  const showDrawer = itemsWithIds.length > previewItems.length

  // Add button to open drawer if there are additional items to show
  const footerButtonProps = showDrawer
    ? {
        onClick: () => setIsDrawerOpen(true),
        count: itemsWithIds.length,
      }
    : undefined

  return (
    <div className="tmp-mt-3" data-testid="token-metadata-preview">
      <MetadataPreviewTable
        items={previewItems}
        footerButtonProps={footerButtonProps}
        trailingFooterContent={
          (metadataQuery.isLoading && (
            <div className="d-flex flex-items-center gap-2">
              <Spinner size="small" />
              <span>{loadingMsg}</span>
            </div>
          )) ||
          (metadataQuery.isError && <span className="fgColor-danger">{errorMsg}</span>)
        }
      />

      {showDrawer && (
        <MetadataDrawer
          /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
          title="Token Metadata"
          isOpen={isDrawerOpen}
          groups={[{name: label, items: itemsWithIds}]}
          onClose={() => setIsDrawerOpen(false)}
        />
      )}
    </div>
  )
}

function buildMetadataItemsForTokenType(
  metadata: PartnerTokenMetadata | null | undefined,
  ownerLogin: string,
  getHovercardAttributesForType: GetHovercardAttributesForTypeFn,
  // TODO: Temporary until backwards compatible KVPs are removed
  includeStoredMetadata?: boolean,
) {
  if (!metadata) return []
  if (metadata.github_metadata) {
    return buildGitHubTokenMetadataItemsFromStoredMetadata(metadata, ownerLogin, getHovercardAttributesForType)
  }
  return buildPartnerMetadataItems(metadata, includeStoredMetadata)
}

function buildPartnerMetadataItems(metadata: PartnerTokenMetadata | null | undefined, includeStoredMetadata?: boolean) {
  if (!metadata) return []
  const items: Array<{field: string; value: string; showCopyButton: boolean}> = []

  if (metadata.secret_id) items.push({field: MetadataKeys.TokenID, value: metadata.secret_id, showCopyButton: true})
  if (metadata.secret_name)
    items.push({field: MetadataKeys.TokenName, value: metadata.secret_name, showCopyButton: true})
  if (metadata.owner_id) items.push({field: MetadataKeys.UserID, value: metadata.owner_id, showCopyButton: true})
  if (metadata.owner_name) items.push({field: MetadataKeys.UserName, value: metadata.owner_name, showCopyButton: true})
  if (metadata.owner_email) items.push({field: MetadataKeys.Email, value: metadata.owner_email, showCopyButton: true})
  if (metadata.org_name) items.push({field: MetadataKeys.Organization, value: metadata.org_name, showCopyButton: true})
  if (metadata.org_id) items.push({field: MetadataKeys.OrganizationID, value: metadata.org_id, showCopyButton: true})
  if (metadata.secret_issued_at)
    items.push({
      field: MetadataKeys.SecretIssuedDate,
      value: formatMetadata(MetadataKeys.SecretIssuedDate, metadata.secret_issued_at),
      showCopyButton: true,
    })
  if (metadata.secret_expires_at)
    items.push({
      field: MetadataKeys.SecretExpiryDate,
      value: formatMetadata(MetadataKeys.SecretExpiryDate, metadata.secret_expires_at),
      showCopyButton: true,
    })
  if (metadata.secret_last_used_at)
    items.push({
      field: MetadataKeys.SecretLastUsedDate,
      value: formatMetadata(MetadataKeys.SecretLastUsedDate, metadata.secret_last_used_at),
      showCopyButton: true,
    })

  // TODO: Remove conditional check once backwards compatible KVPs are removed
  if (!includeStoredMetadata) {
    for (const {key, value} of metadata.kvps ?? []) {
      items.push({field: key, value: formatMetadata(key, value), showCopyButton: true})
    }
  }

  return items
}

// Deprecated: Used for non-stored metadata, which we're migrating away from
function buildGitHubTokenMetadataItems(
  {name, link, owner, created_at, expires_at, last_accessed_at, is_owner_suspended}: TokenMetadata,
  getHovercardAttributesForType: GetHovercardAttributesForTypeFn,
) {
  const items = []

  if (name)
    items.push({
      field: MetadataKeys.TokenName,
      value: name,
      showCopyButton: true,
      ...(link && {
        trailingContent: <Link href={link}>{name}</Link>,
      }),
    })

  if (owner)
    items.push({
      field: MetadataKeys.SecretOwner,
      value: owner.display_login,
      trailingContent: (
        <ActionList variant="full" className="ml-n2">
          <ActionList.LinkItem
            href={`/${owner.display_login}/`}
            {...getHovercardAttributesForType('user', {login: owner.display_login})}
          >
            {owner.avatar_url && (
              <ActionList.LeadingVisual>
                <GitHubAvatar src={owner.avatar_url} />
              </ActionList.LeadingVisual>
            )}
            <span>{owner.display_login}</span>
            {is_owner_suspended && (
              <>
                {' '}
                <small>(suspended)</small>
              </>
            )}
          </ActionList.LinkItem>
        </ActionList>
      ),
    })

  items.push(
    {
      field: MetadataKeys.SecretIssuedDate,
      value: formattedDateString(created_at),
    },
    {
      field: MetadataKeys.SecretExpiryDate,
      value: expires_at ? formattedDateString(expires_at) : 'Secret does not expire',
    },
    {
      field: MetadataKeys.SecretLastUsedDate,
      value: last_accessed_at ? formattedDateString(last_accessed_at) : 'Never used',
    },
  )

  return items
}

function buildGitHubTokenMetadataItemsFromStoredMetadata(
  metadata: PartnerTokenMetadata,
  ownerLogin: string,
  getHovercardAttributesForType: GetHovercardAttributesForTypeFn,
) {
  const items: Array<{field: string; value: string; showCopyButton?: boolean; trailingContent?: React.ReactNode}> = []
  const ghMeta = metadata.github_metadata

  if (metadata.secret_name)
    items.push({
      field: MetadataKeys.TokenName,
      value: metadata.secret_name,
      showCopyButton: true,
      ...(ghMeta?.link && {
        trailingContent: <Link href={ghMeta.link}>{metadata.secret_name}</Link>,
      }),
    })

  if (ghMeta?.owner) {
    items.push({
      field: MetadataKeys.SecretOwner,
      value: ghMeta.owner.display_login,
      trailingContent: (
        <ActionList variant="full" className="ml-n2">
          <ActionList.LinkItem
            href={`/${ghMeta.owner.display_login}/`}
            {...getHovercardAttributesForType('user', {login: ghMeta.owner.display_login})}
          >
            {ghMeta.owner.avatar_url && (
              <ActionList.LeadingVisual>
                <GitHubAvatar src={ghMeta.owner.avatar_url} />
              </ActionList.LeadingVisual>
            )}
            <span>{ghMeta.owner.display_login}</span>
            {ghMeta.is_owner_suspended && (
              <>
                {' '}
                <small>(suspended)</small>
              </>
            )}
          </ActionList.LinkItem>
        </ActionList>
      ),
    })
  } else if (metadata.owner_name) {
    items.push({
      field: MetadataKeys.SecretOwner,
      value: metadata.owner_name,
    })
  }

  items.push({
    field: MetadataKeys.SecretIssuedDate,
    value: metadata.secret_issued_at ? formattedDateString(metadata.secret_issued_at) : '',
  })
  items.push({
    field: MetadataKeys.SecretExpiryDate,
    value: metadata.secret_expires_at ? formattedDateString(metadata.secret_expires_at) : 'Secret does not expire',
  })
  items.push({
    field: MetadataKeys.SecretLastUsedDate,
    value: metadata.secret_last_used_at ? formattedDateString(metadata.secret_last_used_at) : 'Never used',
  })
  if (metadata.org_access) {
    items.push({
      field: MetadataKeys.OrganizationAccess,
      value: formatOrgAccess(metadata.org_access, ownerLogin),
    })
  }

  // TODO: Uncomment this once backwards compatible KVPs are removed
  // for (const {key, value} of metadata.kvps ?? []) {
  //   items.push({field: key, value: formatMetadata(key, value), showCopyButton: true})
  // }

  return items
}
