import {TokenAccess} from '../../../types/token-metadata-types'

import {MetadataKeys} from './MetadataKeys'
import type {MetadataKey} from './MetadataKeys'

type DateMetadataKey =
  | typeof MetadataKeys.SecretIssuedDate
  | typeof MetadataKeys.SecretExpiryDate
  | typeof MetadataKeys.SecretLastUsedDate

const isDateKey = (key: MetadataKey): key is DateMetadataKey =>
  key === MetadataKeys.SecretIssuedDate ||
  key === MetadataKeys.SecretExpiryDate ||
  key === MetadataKeys.SecretLastUsedDate

export function formatMetadata(key: MetadataKey, value: string) {
  if (!isDateKey(key)) return value

  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return value

  return date.toLocaleDateString(undefined, {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  })
}

export function formattedDateString(dateString: string) {
  const date = new Date(dateString)
  if (Number.isNaN(date.getTime())) return dateString

  return date.toLocaleDateString('en-US', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  })
}

export function getTokenAccessPrefix(orgAccess: TokenAccess) {
  switch (orgAccess) {
    case TokenAccess.OrgAccess:
    case TokenAccess.PublicAccess:
      return `Access to `
    case TokenAccess.SSOAccess:
      return `SSO access to `
    default:
      return `No access to `
  }
}
