import {Flash, IconButton} from '@primer/react'
import {XIcon} from '@primer/octicons-react'
import {useEffect, useRef} from 'react'

import styles from './ErrorBanner.module.css'

export function ErrorBanner({visible, message, onDismiss}: {visible: boolean; message: string; onDismiss: () => void}) {
  const buttonRef = useRef<HTMLButtonElement | null>(null) // Initialize with null

  useEffect(() => {
    if (buttonRef.current && visible) {
      buttonRef.current.focus()
    }
  }, [visible])

  if (!visible) {
    return null
  }
  return (
    <Flash variant="danger" full data-testid="error-banner">
      <div aria-atomic="true" role="alert" className={styles.Box}>
        <span className={styles.Text}>{message}</span>
        <IconButton
          aria-label="Dismiss this message"
          size="small"
          variant="invisible"
          icon={XIcon}
          data-testid="dismiss-error-button"
          onClick={onDismiss}
          ref={buttonRef}
          className={styles.IconButton}
        />
      </div>
    </Flash>
  )
}
