import {useMutation} from '@github-ui/react-query'
import {reactFetchJSON} from '@github-ui/verified-fetch'

import {secretScanningUpdateClosureRequestPath} from '../paths'

export function useCancelClosureRequestMutation({
  owner,
  repoName,
  closureRequestNumber,
  onSuccess,
  onError,
}: {
  owner: string
  repoName: string
  closureRequestNumber: number
  onSuccess?: () => void
  onError?: (error: Error) => void
}) {
  return useMutation({
    mutationFn: async () => {
      const url = secretScanningUpdateClosureRequestPath(owner, repoName, closureRequestNumber)
      const response = await reactFetchJSON(url, {
        method: 'PUT',
        body: {
          status: 'cancel',
          repository: repoName,
        },
      })
      if (!response.ok) {
        throw new Error('Error: Unable to cancel alert dismissal request')
      }
    },
    onSuccess,
    onError,
  })
}

export function useUpdateClosureRequestMutation({
  owner,
  repoName,
  closureRequestNumber,
  onSuccess,
  onError,
}: {
  owner: string
  repoName: string
  closureRequestNumber: number
  onSuccess?: () => void
  onError?: (error: Error) => void
}) {
  return useMutation({
    mutationFn: async ({status, message}: {status: string; message: string}) => {
      const url = secretScanningUpdateClosureRequestPath(owner, repoName, closureRequestNumber)
      const response = await reactFetchJSON(url, {
        method: 'PUT',
        body: {
          status,
          message,
          repository: repoName,
        },
      })
      const data = await response.json()
      if (response.status !== 201) {
        return data?.error
      }
      return null
    },
    onSuccess,
    onError,
  })
}
