import {ssrSafeDocument} from '@github-ui/ssr-utils'
import {Button, CounterLabel, Stack} from '@primer/react'
import {useEffect, useState} from 'react'
import {flushSync} from 'react-dom'

import styles from './MetadataPreviewTable.module.css'
import {MetadataTable} from './MetadataTable'
import type {MetadataPreviewTableProps} from './types'

export const MetadataPreviewTable = ({
  items,
  headerProps,
  footerButtonProps,
  trailingFooterContent,
  onCopy,
}: MetadataPreviewTableProps) => {
  const [transitionedItems, setTransitionedItems] = useState(items)
  const supportsViewTransitions = !!ssrSafeDocument && 'startViewTransition' in ssrSafeDocument

  useEffect(() => {
    const transition = ssrSafeDocument?.startViewTransition?.(() =>
      // eslint-disable-next-line @eslint-react/dom/no-flush-sync -- required for View Transitions API to capture old/new DOM snapshots
      flushSync(() => setTransitionedItems(items)),
    )
    if (!transition) return
    // eslint-disable-next-line github/no-then -- swallow expected rejections when a transition is skipped or interrupted
    transition.ready.catch(() => {})
    // eslint-disable-next-line github/no-then -- swallow expected rejections when a transition is skipped or interrupted
    transition.finished.catch(() => {})
  }, [items])

  const displayedItems = supportsViewTransitions ? transitionedItems : items

  const hasFooterContent = footerButtonProps || trailingFooterContent

  return (
    <div className={styles.MetadataPreviewTableTransition}>
      <MetadataTable
        items={displayedItems}
        title={headerProps?.title}
        footerContent={
          hasFooterContent ? (
            <Stack direction="horizontal" align="center">
              {footerButtonProps && (
                <Button
                  size="small"
                  onClick={footerButtonProps.onClick}
                  trailingVisual={() => <CounterLabel>{footerButtonProps.count}</CounterLabel>}
                >
                  {footerButtonProps.label ?? 'View all fields'}
                </Button>
              )}
              {trailingFooterContent}
            </Stack>
          ) : undefined
        }
        onCopy={onCopy}
      />
    </div>
  )
}

export default MetadataPreviewTable
