import {useEffect} from 'react'
import type {UseQueryResult} from '@github-ui/react-query'
import {announce} from '@github-ui/aria-live'

// Announces voice over for async states.
// They're not normally announced cuz they're not wrapped in a live region.
export function useAnnounceAsyncStates<T, E>({
  query,
  loadingMsg,
  errorMsg,
}: {
  query: UseQueryResult<T, E>
  loadingMsg: string
  errorMsg: string
}) {
  useEffect(() => {
    if (query.isLoading) {
      announce(loadingMsg)
    }
  }, [query.isLoading, loadingMsg])
  useEffect(() => {
    if (query.isError) {
      announce(errorMsg)
    }
  }, [query.isError, errorMsg])
  return {loadingMsg, errorMsg}
}
