import {MetadataTable} from './MetadataTable'
import type {MetadataGroupTableProps} from './types'

/**
 * A simple group table component that displays a title and metadata table.
 *
 * Use this component when you want to render a single metadata group with
 * a title and optional footer content.
 */
export const MetadataGroupTable = ({group: {name, items, footerComponents}, onCopy}: MetadataGroupTableProps) => (
  <MetadataTable withBorder title={name} items={items} footerContent={footerComponents} onCopy={onCopy} />
)

export default MetadataGroupTable
