import {Spinner, Timeline} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {ShieldIcon} from '@primer/octicons-react'
import {use} from 'react'
import {useQuery} from '@github-ui/react-query'
import {queries} from '../../api/index'
import {AlertTimeline} from './AlertTimeline'
import type {Repository} from '../../types/repo-types'
import {TimelineContext} from '../shared/TimelineContext'

export function ShowTimeline({
  alertNumber,
  repository,
  isClosed,
}: {
  alertNumber: number
  repository: Repository
  isClosed: boolean
}) {
  const {shouldRefetchTimeline} = use(TimelineContext)

  const {data: timeline, isError} = useQuery(
    queries.timeline(alertNumber, repository.owner_display_login, repository.name, shouldRefetchTimeline),
  )

  return timeline ? <AlertTimeline timeline={timeline} isClosed={isClosed} /> : <LoadingTimeline error={isError} />
}

// Component that renders a loading spinner as a timeline event.
// If timelineError is true then it renders an error message instead.
function LoadingTimeline({error}: {error: boolean}) {
  return (
    <Timeline.Item>
      <Timeline.Badge>
        <Octicon icon={ShieldIcon} />
      </Timeline.Badge>
      <Timeline.Body className="d-flex flex-items-center">
        {error ? (
          <span>Loading timeline failed</span>
        ) : (
          <>
            <span>{'Loading'}</span>
            <Spinner size={'small'} className="ml-2" />
          </>
        )}
      </Timeline.Body>
    </Timeline.Item>
  )
}
