import {Label} from '@primer/react'
import type {Alert} from '../../../types/alert-types'
import {TokenMetadataSection} from './TokenMetadataSection'

export function TokenTagsPane({alert}: {alert: Alert}) {
  return (
    <TokenMetadataSection sectionName="Tags">
      {alert.publicly_leaked && <Label variant="danger">Public leak</Label>}
      {alert.publicly_leaked && alert.multi_repo && ' '}
      {alert.multi_repo && <Label>Multi-repository</Label>}
    </TokenMetadataSection>
  )
}
