import {ActionList, Heading, Link, PageLayout} from '@primer/react'
import {Octicon} from '@primer/react/deprecated'
import {AlertIcon} from '@primer/octicons-react'
import {AssigneesSection} from '@github-ui/security-products-alert-assignees/components/AssigneesSection'
import {AlertMetadata} from '@github-ui/platform-patterns/AlertPageSidebar'
import {ShowHeader} from '../components/show/ShowHeader'
import {Remediation} from '../components/show/remediation/Remediation'
import {ShowLocations} from '../components/show/ShowLocations'
import {ShowTimeline} from '../components/show/ShowTimeline'
import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {Alert} from '../types/alert-types'
import type {Location} from '../types/location-types'
import type {TokenCampaignMetadata} from '../types/token-metadata-types'
import type {User} from '../types/user-types'
import {ErrorContextBanner} from '../components/shared/ErrorContextBanner'
import {ErrorContextProvider} from '../components/shared/ErrorContext'
import {TimelineContextProvider, TimelineContext} from '../components/shared/TimelineContext'
import {use} from 'react'
import {CurrentUserProvider} from '@github-ui/current-user'
import {TokenTypePane} from '../components/show/metadata/TokenTypePane'
import {TokenTagsPane} from '../components/show/metadata/TokenTagsPane'
import {RelatedAlertsPane} from '../components/show/metadata/RelatedAlertsPane'
import {RelatedPublicLeaksPane} from '../components/show/metadata/RelatedPublicLeaksPane'
import {GitHubTokenMetadataPane} from '../components/show/metadata/GitHubTokenMetadataPane'
import {AnalyticsProvider} from '@github-ui/analytics-provider'
import {assignAlertPath, availableAssigneesPath} from '../paths'
import {PartnerTokenMetadataPane} from '../components/show/metadata/PartnerTokenMetadataPane'

import {isEnterprise} from '@github-ui/runtime-environment'
import type {ShowPayload} from '../types/pages'

export function ShowPage() {
  const payload = useRoutePayload<ShowPayload | null>()
  if (!payload || !payload.alert) {
    return <Error />
  }

  const user = payload.current_user
  const locations = payload.locations || []

  return (
    <Providers user={user}>
      <ErrorContextBanner />
      <PageLayout>
        <PageLayout.Header>
          <ShowHeader
            alert={payload.alert}
            repository={payload.repository}
            patternInfo={payload.pattern_info}
            commitAuthorMode={payload.commit_author_mode}
            showUserFeedbackLink={payload.show_user_feedback_link}
            userFeedbackNotice={payload.user_feedback_notice}
            resolveAlertsAllowed={payload.resolve_alerts_allowed}
            delegatedClosuresEnabled={payload.delegated_closures_enabled}
            existingClosureRequestNumber={payload.existing_closure_request_number}
            existingClosureRequestPending={payload.existing_closure_request_pending}
            userCanReviewClosureRequests={payload.user_can_review_closure_requests}
            selfServeBanner={payload.self_serve_banner}
          />
        </PageLayout.Header>
        <PageLayout.Content as="div">
          <Remediation
            alert={payload.alert}
            hostName={payload.host_name}
            repo={payload.repository}
            automaticPartnerValidityChecksEnabled={payload.automatic_partner_validity_checks_enabled}
            oneClickReportingAvailable={payload.one_click_reporting_enabled}
            tokenMetadata={payload.token_metadata}
            partnerMetadataEnabled={payload.partner_metadata_enabled}
            includeStoredMetadata={payload.include_stored_metadata}
          />
          {areLocationsAvailable(locations) && (
            <ShowLocations
              alertNumber={payload.alert.number}
              locations={locations}
              repository={payload.repository}
              totalLocationsCount={payload.total_locations_count}
              page={payload.page}
              locationsPerPage={payload.locations_per_page}
              hasIgnoredLocations={payload.has_ignored_locations}
              ignoredLocationsPath={payload.ignored_locations_path}
              wikiIncrementalScansEnabled={payload.wiki_incremental_scans_enabled}
            />
          )}
          <ShowTimeline
            alertNumber={payload.alert.number}
            repository={payload.repository}
            isClosed={payload.alert.is_closed}
          />
        </PageLayout.Content>
        <PageLayout.Pane>
          <AlertMetadata>
            Tried our new features?{' '}
            <Link href="https://gh.io/secret-scanning-feedback" inline>
              Give feedback
            </Link>
          </AlertMetadata>
          <TokenTypePane alert={payload.alert} />
          {showMetadataTags(payload.alert) && <TokenTagsPane alert={payload.alert} />}
          <Assignment payload={payload} />
          <CampaignPane payload={payload} />
          {showRelatedAlerts(payload.alert) && (
            <RelatedAlertsPane relatedAlerts={payload.related_alerts} repository={payload.repository} />
          )}
          {showRelatedPublicLeaks(payload.alert) && (
            <RelatedPublicLeaksPane relatedPublicLeaks={payload.related_public_leaks} repository={payload.repository} />
          )}
          {!payload.alert.feature_flags?.secret_scanning_metadata_preview_table && (
            <>
              {payload.token_metadata && (
                <GitHubTokenMetadataPane
                  metadata={payload.token_metadata}
                  repository={payload.repository}
                  tokenNumber={payload.alert.number}
                  label={payload.alert.label}
                  alertValidity={payload.alert.validity}
                />
              )}
              {payload.alert.partner_metadata_supported && payload.alert.token_type_provider !== 'GitHub' && (
                <PartnerTokenMetadataPane
                  enabled={payload.partner_metadata_enabled}
                  canManageRepoSecurity={payload.can_manage_repo_security}
                  alert={payload.alert}
                  repo={payload.repository}
                />
              )}
            </>
          )}
        </PageLayout.Pane>
      </PageLayout>
    </Providers>
  )
}

function Providers({user, children}: {user: User; children: React.ReactNode}) {
  return (
    <ErrorContextProvider>
      <CurrentUserProvider user={user}>
        <AnalyticsProvider appName="secret-scanning" category="remediation" metadata={{}}>
          <TimelineContextProvider>{children}</TimelineContextProvider>
        </AnalyticsProvider>
      </CurrentUserProvider>
    </ErrorContextProvider>
  )
}

function areLocationsAvailable(locations: Location[]) {
  return locations.length > 0
}

function showMetadataTags(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_metadata_tags) {
    return false
  }

  return alert.publicly_leaked || alert.multi_repo
}

function showRelatedAlerts(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_related_alerts) {
    return false
  }
  return alert.multi_repo
}

function showRelatedPublicLeaks(alert: Alert) {
  if (!alert.feature_flags?.secret_scanning_show_single_alert_view_related_alerts) {
    return false
  }
  return alert.publicly_leaked
}

function Assignment({payload}: {payload: ShowPayload}) {
  // Refresh timeline after every assignment change
  const {signalTimelineRefetch} = use(TimelineContext)

  return (
    <AssigneesSection
      availableAssigneesPath={availableAssigneesPath({
        owner: payload.repository.owner_display_login,
        repo: payload.repository.name,
      })}
      updateAssigneesPath={assignAlertPath({
        owner: payload.repository.owner_display_login,
        repo: payload.repository.name,
        alertNumber: payload.alert.number,
      })}
      currentUser={payload.current_user}
      assignees={payload.alert.assigned_users ?? []}
      readonly={!payload.is_security_user}
      maxAssignees={1}
      onAssignmentChange={signalTimelineRefetch}
    />
  )
}

function CampaignPane({payload}: {payload: ShowPayload}) {
  if (isEnterprise()) {
    return null
  }
  if (!payload.campaign)
    return (
      <AlertMetadata title="Security campaigns" testId="campaign-section">
        No campaign is currently tracking this alert.
      </AlertMetadata>
    )
  const {campaign, repository, can_view_campaign} = payload
  return (
    <AlertMetadata title="Security campaigns" testId="campaign-section">
      <ActionList variant="full">
        {can_view_campaign ? (
          <ActionList.LinkItem
            data-testid="campaign-link"
            href={`/orgs/${repository.owner_display_login}/security/campaigns/${campaign.number}`}
          >
            {campaign.name}
            <ActionList.Description variant="block">{formatCampaign(campaign)}</ActionList.Description>
          </ActionList.LinkItem>
        ) : (
          <ActionList.Item data-testid="disabled-campaign-link" inactiveText={campaign.name}>
            <ActionList.Description variant="block">{formatCampaign(campaign)}</ActionList.Description>
          </ActionList.Item>
        )}
      </ActionList>
    </AlertMetadata>
  )
}

function formatCampaign(campaign: TokenCampaignMetadata) {
  const percent = campaign.completion_percentage
  const hasPercent = typeof percent === 'number' && !Number.isNaN(percent)
  const due = new Date(campaign.ends_at)
  const isOverdue = due.getTime() < Date.now()
  const dueString = `${isOverdue ? 'overdue' : 'due'} ${due.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
  })}`

  return hasPercent ? `${percent}% complete, ${dueString}` : dueString
}

function Error() {
  return (
    <div className="d-flex flex-column flex-justify-center flex-items-center width-full height-screen">
      <Octicon icon={AlertIcon} className="tmp-mb-4" size={24} />
      <Heading as="h1">Loading secret failed</Heading>
      <span>
        We track these errors automatically, but if the problem persists feel free to
        <Link href="https://support.github.com/" inline>
          {' '}
          contact us
        </Link>
        .
      </span>
    </div>
  )
}
