import {useQuery} from '@github-ui/react-query'

import {metadataQueries} from '../../../api/metadata'
import {TokenAccess} from '../../../types/token-metadata-types'
import {OwnerType} from '../../../types/repo-types'

import type {Repository} from '../../../types/repo-types'
import type {TokenMetadata} from '../../../types/token-metadata-types'

import {getTokenAccessPrefix} from '../metadata/utils'

type UseGetOrgAccessProps = {
  alertNumber: number
  repo: Repository
  tokenMetadata?: TokenMetadata
}

// TODO: Remove after shipping stored metadata
// Deprecated: Included in stored metadata payload
export function useGetOrgAccess({alertNumber: tokenNumber, repo, tokenMetadata}: UseGetOrgAccessProps) {
  const {name, owner_display_login: owner, owner_type} = repo
  const {access_id: accessId = 0, token_type: tokenType = ''} = tokenMetadata ?? {}
  const shouldFetchOrgAccess = Boolean(tokenMetadata) && owner_type === OwnerType.OrgOwner

  const {data, isLoading, isError} = useQuery({
    ...metadataQueries.orgAccess(tokenNumber, owner, name, accessId, tokenType),
    enabled: shouldFetchOrgAccess,
  })

  if (!shouldFetchOrgAccess) return undefined
  if (isLoading) return 'Loading organization access…'
  if (isError || !data) return 'Failed to load organization access'

  return formatOrgAccess(data, owner)
}

// TODO: After removing useGetOrgAccess, move this to the metadata preview component.
// Not doing it now to prevent a circular dependency.
export function formatOrgAccess(orgAccess: TokenAccess, repoOwner: string) {
  const prefix = getTokenAccessPrefix(orgAccess)
  const suffix = orgAccess === TokenAccess.PublicAccess ? ' (public resources only)' : ''
  return `${prefix}${repoOwner}${suffix}`
}
